bool loc_allow(const SmzWorld *w, int loc, int item, const SmzProg *p)
{
    (void)w; (void)item; (void)p;
    switch (loc) {
    case LOC_SwampPalaceEntrance: return w->zelda_keysanity || (item == ITEM_KeySP);
    case LOC_SkullWoodsPinballRoom: return (item == ITEM_KeySW);
    case LOC_TurtleRockBigChest: return (item != ITEM_BigKeyTR);
    case LOC_GanonsTowerBigChest: return (item != ITEM_BigKeyGT);
    case LOC_GanonsTowerPreMoldormChest: return (item != ITEM_BigKeyGT);
    case LOC_GanonsTowerMoldormChest: return (item != ITEM_KeyGT && item != ITEM_BigKeyGT);
    case LOC_GanonsTowerMiniHelmasaurRoomLeft: return (item != ITEM_BigKeyGT);
    case LOC_GanonsTowerMiniHelmasaurRoomRight: return (item != ITEM_BigKeyGT);
    case LOC_LinksUncle: return w->zelda_keysanity || !item_is_dungeon(item);
    case LOC_SecretPassage: return w->zelda_keysanity || !item_is_dungeon(item);
    default: return true;
    }
}

bool loc_always_allow(const SmzWorld *w, int loc, int item, const SmzProg *p)
{
    (void)w; (void)item; (void)p;
    switch (loc) {
    case LOC_TowerOfHeraBigKeyChest: return (item == ITEM_KeyTH);
    case LOC_PalaceOfDarknessBigKeyChest: return (item == ITEM_KeyPD) && P_KeyPD(p) >= 5;
    case LOC_PalaceOfDarknessHarmlessHellway: return (item == ITEM_KeyPD) && P_KeyPD(p) >= 5;
    case LOC_SwampPalaceBigChest: return (item == ITEM_BigKeySP);
    case LOC_SkullWoodsBigChest: return (item == ITEM_BigKeySW);
    case LOC_ThievesTownBigChest: return (item == ITEM_KeyTT) && P_Hammer(p);
    case LOC_TurtleRockBigKeyChest: return (item == ITEM_KeyTR) && P_KeyTR(p) >= 3;
    case LOC_GanonsTowerMapChest: return (item == ITEM_KeyGT) && P_KeyGT(p) >= 3;
    default: return false;
    }
}

