bool region_has_item(int region, int item)
{
    switch (region) {
    case REG_CastleTower: return item == ITEM_KeyCT;
    case REG_EasternPalace: return item == ITEM_BigKeyEP || item == ITEM_MapEP || item == ITEM_CompassEP;
    case REG_DesertPalace: return item == ITEM_KeyDP || item == ITEM_BigKeyDP || item == ITEM_MapDP || item == ITEM_CompassDP;
    case REG_TowerOfHera: return item == ITEM_KeyTH || item == ITEM_BigKeyTH || item == ITEM_MapTH || item == ITEM_CompassTH;
    case REG_PalaceOfDarkness: return item == ITEM_KeyPD || item == ITEM_BigKeyPD || item == ITEM_MapPD || item == ITEM_CompassPD;
    case REG_SwampPalace: return item == ITEM_KeySP || item == ITEM_BigKeySP || item == ITEM_MapSP || item == ITEM_CompassSP;
    case REG_SkullWoods: return item == ITEM_KeySW || item == ITEM_BigKeySW || item == ITEM_MapSW || item == ITEM_CompassSW;
    case REG_ThievesTown: return item == ITEM_KeyTT || item == ITEM_BigKeyTT || item == ITEM_MapTT || item == ITEM_CompassTT;
    case REG_IcePalace: return item == ITEM_KeyIP || item == ITEM_BigKeyIP || item == ITEM_MapIP || item == ITEM_CompassIP;
    case REG_MiseryMire: return item == ITEM_KeyMM || item == ITEM_BigKeyMM || item == ITEM_MapMM || item == ITEM_CompassMM;
    case REG_TurtleRock: return item == ITEM_KeyTR || item == ITEM_BigKeyTR || item == ITEM_MapTR || item == ITEM_CompassTR;
    case REG_GanonsTower: return item == ITEM_KeyGT || item == ITEM_BigKeyGT || item == ITEM_MapGT || item == ITEM_CompassGT;
    case REG_HyruleCastle: return item == ITEM_KeyHC || item == ITEM_MapHC;
    default: return false;
    }
}
